cypress_script:
describe('Contact Form Validation', () => {
  it('should submit the form successfully with valid data', () => {
    cy.visit('https://practicesoftwaretesting.com/contact');
    cy.get('#first_name').type('John');
    cy.get('#last_name').type('Doe');
    cy.get('#email').type('john.doe@example.com');
    cy.get('#message').type('This is a test message.');
    cy.get('#subject').select('Customer service');
    cy.get('[data-test="contact-submit"]').click();
    cy.url().should('include', '/contact');
  });

  it('should show validation errors when required fields are empty', () => {
    cy.visit('https://practicesoftwaretesting.com/contact');
    cy.get('[data-test="contact-submit"]').click();
    cy.get('#first_name').should('have.class', 'ng-invalid');
    cy.get('#last_name').should('have.class', 'ng-invalid');
    cy.get('#email').should('have.class', 'ng-invalid');
    cy.get('#message').should('have.class', 'ng-invalid');
  });
});

playwright_script:
import { test } from '@playwright/test';

test.describe('Contact Form Validation', () => {
  test('should submit the form successfully with valid data', async ({ page }) => {
    await page.goto('https://practicesoftwaretesting.com/contact');
    await page.fill('#first_name', 'John');
    await page.fill('#last_name', 'Doe');
    await page.fill('#email', 'john.doe@example.com');
    await page.fill('#message', 'This is a test message.');
    await page.selectOption('#subject', 'customer-service');
    await page.click('[data-test="contact-submit"]');
    await page.waitForURL('**/contact');
  });

  test('should show validation errors when required fields are empty', async ({ page }) => {
    await page.goto('https://practicesoftwaretesting.com/contact');
    await page.click('[data-test="contact-submit"]');
    const firstName = await page.locator('#first_name');
    const lastName = await page.locator('#last_name');
    const email = await page.locator('#email');
    const message = await page.locator('#message');
    await expect(firstName).toHaveClass(/ng-invalid/);
    await expect(lastName).toHaveClass(/ng-invalid/);
    await expect(email).toHaveClass(/ng-invalid/);
    await expect(message).toHaveClass(/ng-invalid/);
  });
});
